import org.openqa.selenium.*;

public class CheckoutPage {
    private final WebDriver driver;
    private final By email = By.id("email");
    private final By place = By.id("place");
    private final By banner = By.id("order-banner");

    public CheckoutPage(WebDriver driver) { this.driver = driver; }

    public String placeOrder(String email) {
        driver.findElement(this.email).sendKeys(email);
        driver.findElement(place).click();
        return driver.findElement(banner).getText();
    }
}

